CREATE TABLE systems(system_namespace text PRIMARY KEY CHECK(length(system_namespace)>0), created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE imports(import_id text PRIMARY KEY,system_namespace text NOT NULL REFERENCES systems,manifest_sha256 text NOT NULL CHECK(manifest_sha256 ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,state text NOT NULL DEFAULT 'sealed' CHECK(state IN ('staging','sealed','failed')), UNIQUE(import_id,system_namespace));
CREATE TABLE entities(entity_id text PRIMARY KEY,system_namespace text NOT NULL REFERENCES systems,kind text NOT NULL,qualified_identity jsonb NOT NULL,identity jsonb NOT NULL,parent_id text, UNIQUE(system_namespace,kind,qualified_identity),UNIQUE(entity_id,system_namespace),FOREIGN KEY(parent_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE INDEX entity_namespace_kind ON entities(system_namespace,kind);
CREATE TABLE runs(run_id text PRIMARY KEY,system_namespace text NOT NULL REFERENCES systems,import_id text NOT NULL,payload jsonb NOT NULL,state text NOT NULL CHECK(state IN ('queued','running','cancel_requested','succeeded','partial','failed','cancelled')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,UNIQUE(run_id,system_namespace),FOREIGN KEY(import_id,system_namespace) REFERENCES imports(import_id,system_namespace),CHECK((state IN ('succeeded','partial','failed','cancelled'))=(completed_at IS NOT NULL)));
CREATE INDEX runs_namespace_state ON runs(system_namespace,state,created_at);
CREATE TABLE entity_observations(observation_id text PRIMARY KEY,run_id text NOT NULL,entity_id text NOT NULL,system_namespace text NOT NULL,observation_digest text NOT NULL,payload jsonb NOT NULL,UNIQUE(run_id,entity_id,observation_digest),UNIQUE(observation_id,system_namespace),FOREIGN KEY(run_id,system_namespace) REFERENCES runs(run_id,system_namespace),FOREIGN KEY(entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE TABLE blobs(sha256 text PRIMARY KEY CHECK(sha256 ~ '^[a-f0-9]{64}$'),byte_length bigint NOT NULL CHECK(byte_length>=0),state text NOT NULL DEFAULT 'available' CHECK(state IN ('available','deleting','deleted')),deletion_epoch text,UNIQUE(sha256,byte_length));
CREATE TABLE artifacts(artifact_id text PRIMARY KEY,system_namespace text NOT NULL,import_id text NOT NULL,locator text NOT NULL,sha256 text NOT NULL,byte_length bigint NOT NULL,source_member_id text,payload jsonb NOT NULL,UNIQUE(import_id,locator),UNIQUE(artifact_id,system_namespace),FOREIGN KEY(import_id,system_namespace) REFERENCES imports(import_id,system_namespace),FOREIGN KEY(sha256,byte_length) REFERENCES blobs(sha256,byte_length),FOREIGN KEY(source_member_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE TABLE import_entries(import_id text NOT NULL,locator text NOT NULL,artifact_id text REFERENCES artifacts,scope_state text NOT NULL CHECK(scope_state IN ('supplied','excluded','missing')),payload jsonb NOT NULL,PRIMARY KEY(import_id,locator),FOREIGN KEY(import_id) REFERENCES imports);
CREATE TABLE origin_maps(origin_map_id text PRIMARY KEY,system_namespace text NOT NULL REFERENCES systems,payload jsonb NOT NULL);
CREATE TABLE origin_map_segments(origin_map_id text NOT NULL REFERENCES origin_maps,segment_index integer NOT NULL,artifact_id text NOT NULL,system_namespace text NOT NULL,raw_start bigint NOT NULL,raw_end bigint NOT NULL,CHECK(raw_start>=0 AND raw_end>=raw_start),PRIMARY KEY(origin_map_id,segment_index),FOREIGN KEY(artifact_id,system_namespace) REFERENCES artifacts(artifact_id,system_namespace));
CREATE TABLE run_artifacts(run_id text NOT NULL,artifact_id text NOT NULL,system_namespace text NOT NULL,status text NOT NULL DEFAULT 'imported',PRIMARY KEY(run_id,artifact_id),FOREIGN KEY(run_id,system_namespace) REFERENCES runs(run_id,system_namespace),FOREIGN KEY(artifact_id,system_namespace) REFERENCES artifacts(artifact_id,system_namespace));
CREATE TABLE run_providers(run_id text NOT NULL REFERENCES runs,provider_id text NOT NULL,provider_version text NOT NULL,source_revision text, payload jsonb NOT NULL,UNIQUE NULLS NOT DISTINCT(run_id,provider_id,provider_version,source_revision));
CREATE TABLE evidence(evidence_id text PRIMARY KEY,run_id text NOT NULL,system_namespace text NOT NULL,artifact_id text,record_sha256 text NOT NULL,content_sha256 text NOT NULL,provider_id text NOT NULL,provider_version text NOT NULL,payload jsonb NOT NULL,UNIQUE(evidence_id,system_namespace),FOREIGN KEY(run_id,system_namespace) REFERENCES runs(run_id,system_namespace),FOREIGN KEY(artifact_id,system_namespace) REFERENCES artifacts(artifact_id,system_namespace));
CREATE TABLE evidence_subjects(evidence_id text NOT NULL,entity_id text NOT NULL,system_namespace text NOT NULL,PRIMARY KEY(evidence_id,entity_id),FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace),FOREIGN KEY(entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE TABLE evidence_support(evidence_id text NOT NULL,supporting_id text NOT NULL,system_namespace text NOT NULL,PRIMARY KEY(evidence_id,supporting_id),CHECK(evidence_id<>supporting_id),FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace),FOREIGN KEY(supporting_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace));
CREATE TABLE evidence_contradictions(evidence_id text NOT NULL,contradicting_id text NOT NULL,system_namespace text NOT NULL,PRIMARY KEY(evidence_id,contradicting_id),CHECK(evidence_id<>contradicting_id),FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace),FOREIGN KEY(contradicting_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace));
CREATE TABLE dependencies(dependency_id text PRIMARY KEY,run_id text NOT NULL,system_namespace text NOT NULL,from_entity_id text NOT NULL,to_entity_id text,relationship text NOT NULL,resolution text NOT NULL CHECK(resolution IN ('resolved','ambiguous','dynamic','missing')),payload jsonb NOT NULL,UNIQUE(dependency_id,system_namespace),CHECK((resolution='resolved')=(to_entity_id IS NOT NULL)),FOREIGN KEY(run_id,system_namespace) REFERENCES runs(run_id,system_namespace),FOREIGN KEY(from_entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace),FOREIGN KEY(to_entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE INDEX dependency_from ON dependencies(system_namespace,from_entity_id,relationship);
CREATE INDEX dependency_to ON dependencies(system_namespace,to_entity_id,relationship);
CREATE TABLE dependency_candidates(dependency_id text NOT NULL,entity_id text NOT NULL,system_namespace text NOT NULL,PRIMARY KEY(dependency_id,entity_id),FOREIGN KEY(dependency_id,system_namespace) REFERENCES dependencies(dependency_id,system_namespace),FOREIGN KEY(entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE TABLE dependency_evidence(dependency_id text NOT NULL,evidence_id text NOT NULL,system_namespace text NOT NULL,PRIMARY KEY(dependency_id,evidence_id),FOREIGN KEY(dependency_id,system_namespace) REFERENCES dependencies(dependency_id,system_namespace),FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace));
CREATE TABLE rule_revisions(revision_id text PRIMARY KEY,rule_entity_id text NOT NULL,run_id text NOT NULL,system_namespace text NOT NULL,previous_revision_id text REFERENCES rule_revisions,record_sha256 text NOT NULL,support_fingerprint text NOT NULL,payload jsonb NOT NULL,UNIQUE(revision_id,system_namespace),FOREIGN KEY(run_id,system_namespace) REFERENCES runs(run_id,system_namespace),FOREIGN KEY(rule_entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE TABLE rule_heads(rule_entity_id text PRIMARY KEY REFERENCES entities,revision_id text NOT NULL REFERENCES rule_revisions);
CREATE TABLE rule_evidence(revision_id text NOT NULL,evidence_id text NOT NULL,system_namespace text NOT NULL,PRIMARY KEY(revision_id,evidence_id),FOREIGN KEY(revision_id,system_namespace) REFERENCES rule_revisions(revision_id,system_namespace),FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace));
CREATE TABLE rule_scopes(revision_id text NOT NULL,entity_id text NOT NULL,system_namespace text NOT NULL,scope_kind text NOT NULL,PRIMARY KEY(revision_id,entity_id),FOREIGN KEY(revision_id,system_namespace) REFERENCES rule_revisions(revision_id,system_namespace),FOREIGN KEY(entity_id,system_namespace) REFERENCES entities(entity_id,system_namespace));
CREATE TABLE reviews(review_id text PRIMARY KEY,sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,subject_type text NOT NULL CHECK(subject_type IN ('evidence','dependency','rule_revision')),subject_id text NOT NULL,system_namespace text NOT NULL REFERENCES systems,evidence_id text REFERENCES evidence,dependency_id text REFERENCES dependencies,revision_id text REFERENCES rule_revisions,subject_fingerprint text NOT NULL,previous_review_id text REFERENCES reviews,status text NOT NULL CHECK(status IN ('pending_review','verified','rejected')),actor_id text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(num_nonnulls(evidence_id,dependency_id,revision_id)=1),CHECK((subject_type='evidence' AND subject_id=evidence_id) OR (subject_type='dependency' AND subject_id=dependency_id) OR (subject_type='rule_revision' AND subject_id=revision_id)));
ALTER TABLE reviews ADD FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace),ADD FOREIGN KEY(dependency_id,system_namespace) REFERENCES dependencies(dependency_id,system_namespace),ADD FOREIGN KEY(revision_id,system_namespace) REFERENCES rule_revisions(revision_id,system_namespace);
CREATE TABLE review_heads(subject_type text NOT NULL,subject_id text NOT NULL,review_id text REFERENCES reviews,PRIMARY KEY(subject_type,subject_id));
CREATE TABLE snapshots(snapshot_id text PRIMARY KEY,system_namespace text NOT NULL REFERENCES systems,run_id text NOT NULL,manifest_sha256 text NOT NULL,payload jsonb NOT NULL,review_sequence bigint NOT NULL,UNIQUE(snapshot_id,system_namespace),FOREIGN KEY(run_id,system_namespace) REFERENCES runs(run_id,system_namespace));
CREATE TABLE snapshot_members(snapshot_id text NOT NULL,system_namespace text NOT NULL,observation_id text,evidence_id text,dependency_id text,revision_id text,CHECK(num_nonnulls(observation_id,evidence_id,dependency_id,revision_id)=1),FOREIGN KEY(snapshot_id,system_namespace) REFERENCES snapshots(snapshot_id,system_namespace),FOREIGN KEY(observation_id,system_namespace) REFERENCES entity_observations(observation_id,system_namespace),FOREIGN KEY(evidence_id,system_namespace) REFERENCES evidence(evidence_id,system_namespace),FOREIGN KEY(dependency_id,system_namespace) REFERENCES dependencies(dependency_id,system_namespace),FOREIGN KEY(revision_id,system_namespace) REFERENCES rule_revisions(revision_id,system_namespace),UNIQUE NULLS NOT DISTINCT(snapshot_id,observation_id,evidence_id,dependency_id,revision_id));
CREATE TABLE namespace_heads(system_namespace text PRIMARY KEY REFERENCES systems,snapshot_id text NOT NULL,FOREIGN KEY(snapshot_id,system_namespace) REFERENCES snapshots(snapshot_id,system_namespace));
CREATE TABLE chunks(chunk_id text PRIMARY KEY,snapshot_id text NOT NULL,system_namespace text NOT NULL,policy_version text NOT NULL,provider_version text NOT NULL,tokenizer_version text NOT NULL,fingerprint text NOT NULL,text_content text NOT NULL,search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple',text_content)) STORED,UNIQUE(snapshot_id,policy_version,provider_version,tokenizer_version,fingerprint),FOREIGN KEY(snapshot_id,system_namespace) REFERENCES snapshots(snapshot_id,system_namespace));
CREATE INDEX chunks_keyword ON chunks USING gin(search_vector);
CREATE TABLE chunk_links(chunk_id text NOT NULL REFERENCES chunks,evidence_id text NOT NULL REFERENCES evidence,PRIMARY KEY(chunk_id,evidence_id));
CREATE TABLE idempotency_keys(scope text NOT NULL,key text NOT NULL,request_sha256 text NOT NULL,result_id text NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE audit_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id text NOT NULL,action text NOT NULL,resource_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),payload jsonb NOT NULL);
